#!/usr/bin/env python3
"""A standalone disk-usage collector and tree renderer.

The collector retains directory entry order, then constructs a presentation
reflection.  Reflection input and filesystem input share the same renderer.
Only modules in the Python standard library are used.
"""
from __future__ import annotations

import collections
import difflib
import errno
import json
import math
import os
import re
import signal
import stat
import struct
import sys
import unicodedata
from dataclasses import dataclass, field

from cli_help import LONG_HELP, SHORT_HELP

VERSION = "0.21.1"
SCHEMA = "2024-11-02"
MASK = (1 << 64) - 1
MORE_HELP = "For more information, try '--help'.\n"


def f32(value):
    try:
        return struct.unpack('f', struct.pack('f', value))[0]
    except OverflowError:
        return math.copysign(math.inf, value)


def lossless_display(path):
    return os.fsencode(path).decode('utf-8', 'replace')


def rust_debug(text):
    """The quoted, escaped string notation used in diagnostic messages."""
    out = ['"']
    short = {'\0': '\\0', '\t': '\\t', '\r': '\\r', '\n': '\\n',
             '\\': '\\\\', '"': '\\"'}
    for c in text:
        if c in short:
            out.append(short[c])
        elif unicodedata.category(c) in ('Cc', 'Cf', 'Cs', 'Zl', 'Zp'):
            out.append('\\u{' + format(ord(c), 'x') + '}')
        else:
            out.append(c)
    out.append('"')
    return ''.join(out)


class AppError(Exception):
    def __init__(self, code, message):
        self.code = code
        self.message = message


# ---------------------------------------------------------------------------
# Command line

@dataclass(frozen=True)
class Option:
    name: str
    arity: int = 0
    metavar: str = ''
    choices: tuple = ()
    aliases: tuple = ()
    short: str = ''

    @property
    def label(self):
        return '--' + self.name + ((' ' + self.metavar) if self.metavar else '')


OPTIONS = [
    Option('json-input'), Option('json-output'),
    Option('bytes-format', 1, '<BYTES_FORMAT>', ('plain', 'metric', 'binary'), short='b'),
    Option('deduplicate-hardlinks', aliases=('detect-links', 'dedupe-links'), short='H'),
    Option('top-down'), Option('align-right'),
    Option('quantity', 1, '<QUANTITY>', ('apparent-size', 'block-size', 'block-count'), short='q'),
    Option('max-depth', 1, '<MAX_DEPTH>', aliases=('depth',), short='d'),
    Option('total-width', 1, '<TOTAL_WIDTH>', aliases=('width',), short='w'),
    Option('column-width', 2, '<TREE_WIDTH> <BAR_WIDTH>'),
    Option('min-ratio', 1, '<MIN_RATIO>', short='m'),
    Option('no-sort'), Option('silent-errors', aliases=('no-errors',), short='s'),
    Option('progress', short='p'), Option('threads', 1, '<THREADS>'),
    Option('omit-json-shared-details'), Option('omit-json-shared-summary'),
    Option('help', short='h'), Option('version', short='V'),
]
BY_NAME = {o.name: o for o in OPTIONS}
LONG_OPTIONS = {name: o for o in OPTIONS for name in (o.name,) + o.aliases}
SHORT_OPTIONS = {o.short: o for o in OPTIONS if o.short}


class Arguments:
    def __init__(self, argv):
        self.values = {
            'bytes-format': 'metric', 'quantity': 'block-size',
            'max-depth': 10, 'min-ratio': f32(0.01), 'threads': 'auto',
        }
        self.seen = []
        self.files = []
        self.parse(argv)

    def get(self, key, default=None):
        return self.values.get(key, default)

    def flag(self, key):
        return bool(self.values.get(key, False))

    def usage(self, names=None, required=(), generic=False, files=None):
        if generic:
            return 'Usage: executable [OPTIONS] [FILES]...'
        names = self.seen if names is None else names
        use = []
        for n in list(required) + list(names):
            if n not in use and n not in ('help', 'version'):
                use.append(n)
        items = [BY_NAME[n].label for n in use]
        has_files = bool(self.files) if files is None else files
        items.append('<FILES>...' if has_files else '[FILES]...')
        if not use:
            items.insert(0, '[OPTIONS]')
        return 'Usage: executable ' + ' '.join(items)

    def fail(self, text, usage=None):
        if usage:
            text += '\n\n' + usage
        raise AppError(2, 'error: ' + text + '\n\n' + MORE_HELP)

    def unknown(self, token):
        suggestion = None
        if token.startswith('--'):
            query = token[2:].split('=')[0]
            # Prefer the declared spelling, in declaration order, for equal
            # similarity scores (e.g. --json is nearest to --json-input).
            candidates = []
            for name in LONG_OPTIONS:
                ratio = difflib.SequenceMatcher(None, query, name).ratio()
                if name.startswith(query) and query:
                    ratio = max(ratio, 0.88)
                if ratio > .72:
                    candidates.append((ratio, name))
            if candidates:
                best = max(r for r, n in candidates)
                suggestion = next(n for r, n in candidates if r == best)
        if suggestion:
            text = "unexpected argument '" + token + "' found\n\n  tip: a similar argument exists: '--" + suggestion + "'"
            names = self.seen + [LONG_OPTIONS[suggestion].name]
            self.fail(text, self.usage(names))
        text = "unexpected argument '" + token + "' found\n\n  tip: to pass '" + token + "' as a value, use '-- " + token + "'"
        self.fail(text, self.usage())

    def invalid(self, option, value, reason=None):
        text = "invalid value '" + value + "' for '" + option.label + "'"
        if reason is not None:
            text += ': ' + reason
        if option.choices:
            text += '\n  [possible values: ' + ', '.join(option.choices) + ']'
            choices = difflib.get_close_matches(value, option.choices, 1, .74)
            if choices:
                text += "\n\n  tip: a similar value exists: '" + choices[0] + "'"
        self.fail(text)

    def numeric(self, opt, value, positive=False, prefix=''):
        if not value:
            reason = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'\+?[0-9]+', value):
            reason = 'invalid digit found in string'
        elif int(value) > MASK:
            reason = 'number too large to fit in target type'
        elif positive and int(value) == 0:
            reason = 'number would be zero for non-zero type'
        else:
            return int(value)
        self.invalid(opt, value, prefix + reason)

    def convert(self, opt, values):
        value = values[0] if values else None
        name = opt.name
        if opt.choices:
            if value not in opt.choices:
                self.invalid(opt, value)
            return value
        if name == 'max-depth':
            if value == 'inf':
                return MASK
            return self.numeric(opt, value, True,
                                'Value is neither "inf" nor a positive integer: ')
        if name == 'threads':
            if value in ('auto', 'max'):
                return value
            return self.numeric(opt, value, True,
                                'Value is neither "auto", "max", nor a number: ')
        if name in ('total-width', 'column-width'):
            result = [self.numeric(opt, v) for v in values]
            return result[0] if len(result) == 1 else result
        if name == 'min-ratio':
            if not re.fullmatch(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)', value, re.I):
                self.invalid(opt, value, 'invalid float literal')
            try:
                ratio = f32(float(value))
            except (ValueError, OverflowError):
                self.invalid(opt, value, 'invalid float literal')
            if ratio < 0:
                self.invalid(opt, value, 'less than 0')
            if ratio >= 1:
                self.invalid(opt, value, 'greater than or equal to 1')
            return ratio
        return True

    def missing_value(self, opt, count):
        if count:
            self.fail(str(opt.arity) + " values required for '" + opt.label + "' but " + str(count) + ' was provided', self.usage())
        text = "a value is required for '" + opt.label + "' but none was supplied"
        if opt.choices:
            text += '\n  [possible values: ' + ', '.join(opt.choices) + ']'
        self.fail(text)

    def parse(self, argv):
        index = 0
        positional = False
        while index < len(argv):
            token = argv[index]
            index += 1
            if positional or token == '-' or not token.startswith('-'):
                if token == '':
                    self.fail("a value is required for '[FILES]...' but none was supplied")
                self.files.append(token)
                continue
            if token == '--':
                positional = True
                continue
            if token.startswith('--'):
                key, eq, val = token[2:].partition('=')
                if key not in LONG_OPTIONS:
                    self.unknown('--' + key)
                queue = [(LONG_OPTIONS[key], val if eq else None, token == '--help')]
            else:
                chars = token[1:]
                queue = []
                while chars:
                    ch, chars = chars[0], chars[1:]
                    if ch not in SHORT_OPTIONS:
                        self.unknown('-' + ch)
                    opt = SHORT_OPTIONS[ch]
                    attached = None
                    if opt.arity and chars:
                        attached = chars[1:] if chars.startswith('=') else chars
                        chars = ''
                    queue.append((opt, attached, False))
                    if opt.name in ('help', 'version'):
                        break
            for opt, inline, long_help in queue:
                if opt.name in self.seen:
                    names = [n for n in self.seen if n != opt.name]
                    self.fail("the argument '" + opt.label + "' cannot be used multiple times", self.usage(names))
                if not opt.arity:
                    if inline is not None:
                        self.fail("unexpected value '" + inline + "' for '" + opt.label + "' found; no more were expected", self.usage(self.seen + [opt.name]))
                    if opt.name == 'help':
                        sys.stdout.write(LONG_HELP if long_help else SHORT_HELP)
                        raise SystemExit(0)
                    if opt.name == 'version':
                        sys.stdout.write('pdu ' + VERSION + '\n')
                        raise SystemExit(0)
                    values = []
                else:
                    values = [inline] if inline is not None else []
                    while len(values) < opt.arity and index < len(argv):
                        candidate = argv[index]
                        if candidate.startswith('-') and candidate != '-':
                            if candidate == '--' or candidate.startswith('--') and candidate[2:].split('=')[0] in LONG_OPTIONS or candidate.startswith('-') and len(candidate) > 1 and candidate[1] in SHORT_OPTIONS:
                                break
                            self.unknown(candidate if candidate.startswith('--') else candidate[:2])
                        values.append(candidate)
                        index += 1
                    if len(values) != opt.arity:
                        self.missing_value(opt, len(values))
                    if opt.choices and any(v == '' for v in values):
                        self.missing_value(opt, 0)
                self.values[opt.name] = self.convert(opt, values)
                self.seen.append(opt.name)
        # Argument conflicts are reported in the order in which flags occur.
        conflicts = {
            'json-input': {'quantity', 'deduplicate-hardlinks'},
            'quantity': {'json-input'}, 'deduplicate-hardlinks': {'json-input'},
            'total-width': {'column-width'}, 'column-width': {'total-width'},
        }
        for first in self.seen:
            other = [n for n in self.seen if n in conflicts.get(first, ())]
            if not other:
                continue
            text = "the argument '" + BY_NAME[first].label + "' cannot be used with"
            if len(other) == 1:
                text += " '" + BY_NAME[other[0]].label + "'"
            else:
                text += ':\n' + '\n'.join('  ' + BY_NAME[n].label for n in other)
            self.fail(text, self.usage([n for n in self.seen if n not in other]))
        if self.flag('omit-json-shared-details') or self.flag('omit-json-shared-summary'):
            missing = []
            if not self.flag('json-output'):
                missing.append('json-output')
            if not self.flag('deduplicate-hardlinks') and not (self.flag('json-input') and self.flag('json-output')):
                missing.append('deduplicate-hardlinks')
            if missing:
                text = 'the following required arguments were not provided:\n' + '\n'.join('  ' + BY_NAME[n].label for n in missing)
                self.fail(text, self.usage(required=missing))


# ---------------------------------------------------------------------------
# Reflection records and filesystem collection

@dataclass
class Node:
    name: str
    size: int
    children: list = field(default_factory=list)
    path: str | None = None

    def as_json(self):
        return {'name': self.name, 'size': self.size,
                'children': [child.as_json() for child in self.children]}


def path_components(path):
    parts = path.split('/')
    answer = []
    if path.startswith('/'):
        answer.append('/')
    elif parts and parts[0] == '.':
        answer.append('.')
    answer.extend(p for p in parts if p not in ('', '.'))
    return tuple(answer)


def append_path(parent, name):
    if name.startswith('/') or not parent:
        return name
    return parent + ('' if parent.endswith('/') else '/') + name


class Collector:
    def __init__(self, args):
        self.args = args
        self.links = {}
        self.seen_dirs = set()

    def error(self, operation, path, problem):
        if not self.args.flag('silent-errors'):
            number = problem.errno or errno.EIO
            message = os.strerror(number)
            sys.stderr.write('\r\r[error] ' + operation + ' ' + rust_debug(lossless_display(path)) + ': ' + message + ' (os error ' + str(number) + ')\n')

    def walk(self, path, name):
        try:
            info = os.lstat(path)
        except OSError as ex:
            self.error('symlink_metadata', path, ex)
            return Node(lossless_display(name), 0, path=path)
        quantity = self.args.get('quantity')
        if quantity == 'apparent-size':
            size = info.st_size
        elif quantity == 'block-count':
            size = info.st_blocks
        else:
            size = info.st_blocks * 512
        node = Node(lossless_display(name), size & MASK, path=path)
        is_dir = stat.S_ISDIR(info.st_mode)
        if self.args.flag('deduplicate-hardlinks'):
            if is_dir:
                if info.st_ino in self.seen_dirs:
                    return None
                self.seen_dirs.add(info.st_ino)
            elif info.st_nlink > 1:
                entry = self.links.setdefault(info.st_ino, {
                    'ino': info.st_ino, 'size': size, 'links': info.st_nlink,
                    'paths': {}, 'count': 0, 'occurrences': collections.Counter(),
                })
                components = path_components(path)
                entry['paths'].setdefault(components, lossless_display(path))
                entry['count'] += 1
                entry['occurrences'][components] += 1
        if is_dir:
            try:
                with os.scandir(path) as iterator:
                    names = [item.name for item in iterator]
            except OSError as ex:
                self.error('read_dir', path, ex)
                names = []
            for filename in names:
                child = self.walk(append_path(path, filename), filename)
                if child is not None:
                    node.children.append(child)
                    node.size = (node.size + child.size) & MASK
        return node

    def collect(self):
        roots = []
        for path in self.args.files or ['.']:
            node = self.walk(path, path)
            if node is not None:
                roots.append(node)
        if len(roots) == 1:
            root = roots[0]
        else:
            root = Node('(total)', sum(n.size for n in roots) & MASK, roots)
        total = root.size
        minimum = self.args.get('min-ratio')
        max_depth = self.args.get('max-depth')

        def reflect(node, depth):
            children = []
            if depth < max_depth:
                candidates = node.children
                if not self.args.flag('no-sort'):
                    candidates = sorted(candidates, key=lambda child: -child.size)
                for child in candidates:
                    ratio = f32(f32(child.size) / f32(total)) if total else math.nan
                    if not ratio < minimum:
                        children.append(reflect(child, depth + 1))
            size = node.size
            if self.links:
                components = path_components(node.path) if node.path is not None else None
                for entry in self.links.values():
                    count = sum(c for p, c in entry['occurrences'].items()
                                if components is None or p[:len(components)] == components)
                    if count > 1:
                        size = (size - (count - 1) * entry['size']) & MASK
            return Node(node.name, size, children)

        reflection = reflect(root, 1)
        details = [{k: entry[k] for k in ('ino', 'size', 'links')} |
                   {'paths': list(entry['paths'].values())}
                   for entry in self.links.values()]
        summary = summarize_links(self.links.values(), collected=True) if self.links else None
        sys.stderr.write('\r\r')
        sys.stderr.flush()
        return reflection, details, summary


SUMMARY_FIELDS = ('inodes', 'exclusive_inodes', 'all_links', 'detected_links',
                  'exclusive_links', 'shared_size', 'exclusive_shared_size')


def summarize_links(details, collected=False):
    summary = dict.fromkeys(SUMMARY_FIELDS, 0)
    for entry in details:
        count = entry['count'] if collected else len({path_components(p) for p in entry['paths']})
        exclusive = count == entry['links']
        summary['inodes'] += 1
        summary['all_links'] += entry['links']
        summary['detected_links'] += count
        summary['shared_size'] += entry['size']
        if exclusive:
            summary['exclusive_inodes'] += 1
            summary['exclusive_links'] += count
            summary['exclusive_shared_size'] += entry['size']
    return {k: v & MASK for k, v in summary.items()}


# ---------------------------------------------------------------------------
# JSON reader.  Positions are retained for diagnostics, and object member lists
# preserve duplicate keys so they can be diagnosed rather than silently lost.

@dataclass
class JsonValue:
    kind: str
    value: object
    start: int
    end: int


class JsonReader:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.depth = 0

    def fail(self, message, pos=None):
        if pos is None:
            pos = self.pos
        prefix = self.text[:pos]
        line = prefix.count('\n') + 1
        column = len(prefix.rsplit('\n', 1)[-1].encode('utf-8', 'replace'))
        raise AppError(3, '[error] DeserializationFailure: ' + message + ' at line ' + str(line) + ' column ' + str(column) + '\n')

    def whitespace(self):
        n = len(self.text)
        while self.pos < n and self.text[self.pos] in ' \t\r\n':
            self.pos += 1

    def string(self):
        start = self.pos
        self.pos += 1
        escaped = False
        while self.pos < len(self.text):
            ch = self.text[self.pos]
            self.pos += 1
            if ord(ch) < 32:
                self.fail('control character (\\u0000-\\u001F) found while parsing a string')
            if escaped:
                if ch == 'u':
                    for _ in range(4):
                        if self.pos >= len(self.text):
                            self.fail('EOF while parsing a string')
                        digit = self.text[self.pos]
                        self.pos += 1
                        if digit not in '0123456789abcdefABCDEF':
                            self.fail('invalid escape')
                elif ch not in '"\\/bfnrt':
                    self.fail('invalid escape')
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '"':
                try:
                    result = json.loads(self.text[start:self.pos])
                    result.encode('utf-8')
                except (ValueError, UnicodeEncodeError):
                    self.fail('lone leading surrogate in hex escape')
                return JsonValue('string', result, start, self.pos)
        self.fail('EOF while parsing a string')

    def value(self, top=False):
        self.whitespace()
        start = self.pos
        if self.pos >= len(self.text):
            self.fail('EOF while parsing a value')
        ch = self.text[self.pos]
        if ch == '"':
            return self.string()
        if ch in '[{':
            self.pos += 1
            self.depth += 1
            if self.depth >= 128:
                self.fail('recursion limit exceeded')
            object_kind = ch == '{'
            closing = '}' if object_kind else ']'
            label = 'object' if object_kind else 'list'
            values = []
            known = set()
            self.whitespace()
            if self.pos < len(self.text) and self.text[self.pos] == closing:
                self.pos += 1
                self.depth -= 1
                return JsonValue('map' if object_kind else 'sequence', values, start, self.pos)
            while True:
                self.whitespace()
                if self.pos >= len(self.text):
                    self.fail('EOF while parsing an ' + label if object_kind else 'EOF while parsing a list')
                key = None
                if object_kind:
                    if self.text[self.pos] != '"':
                        self.fail('key must be a string', self.pos + 1)
                    key = self.string()
                    if top and key.value in ('schema-version', 'pdu'):
                        if key.value in known:
                            self.fail('duplicate field `' + key.value + '`', key.end)
                        known.add(key.value)
                    self.whitespace()
                    if self.pos >= len(self.text):
                        self.fail('EOF while parsing an object')
                    if self.text[self.pos] != ':':
                        self.fail('expected `:`', self.pos + 1)
                    self.pos += 1
                val = self.value()
                if top and key is not None:
                    if key.value == 'schema-version':
                        self.check_string(val, val.end)
                        if val.value != SCHEMA:
                            self.fail('InvalidSchema: ' + rust_debug(val.value) + ': input schema is not "' + SCHEMA + '"', min(val.end + 1, len(self.text)))
                    elif key.value == 'pdu' and val.kind != 'null':
                        self.check_string(val, val.end)
                values.append((key, val) if object_kind else val)
                self.whitespace()
                if self.pos >= len(self.text):
                    self.fail('EOF while parsing an object' if object_kind else 'EOF while parsing a list')
                if self.text[self.pos] == closing:
                    self.pos += 1
                    break
                if self.text[self.pos] != ',':
                    self.fail('expected `,` or `}`' if object_kind else 'expected `,` or `]`', self.pos + 1)
                self.pos += 1
                self.whitespace()
                if self.pos < len(self.text) and self.text[self.pos] == closing:
                    self.fail('trailing comma', self.pos + 1)
            self.depth -= 1
            return JsonValue('map' if object_kind else 'sequence', values, start, self.pos)
        if ch in '-0123456789':
            match = re.match(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?', self.text[self.pos:])
            if not match:
                self.pos += 1
                self.fail('invalid number')
            number = match.group()
            self.pos += len(number)
            if self.pos < len(self.text) and self.text[self.pos] in '0123456789.eE':
                self.fail('invalid number', self.pos + 1)
            if any(c in number for c in '.eE') or number == '-0':
                result = float(number)
                kind = 'float'
            else:
                result = int(number)
                kind = 'integer'
                if result > MASK or result < -(1 << 63):
                    result = float(number)
                    kind = 'float'
            if kind == 'float' and math.isinf(result):
                self.fail('number out of range')
            return JsonValue(kind, result, start, self.pos)
        for literal, value, kind in [('true', True, 'boolean'), ('false', False, 'boolean'), ('null', None, 'null')]:
            if ch == literal[0]:
                for wanted in literal:
                    if self.pos >= len(self.text):
                        self.fail('EOF while parsing a value')
                    actual = self.text[self.pos]
                    self.pos += 1
                    if actual != wanted:
                        self.fail('expected ident')
                return JsonValue(kind, value, start, self.pos)
        self.fail('expected value', self.pos + 1)

    @staticmethod
    def describe(value):
        if value.kind == 'string':
            return 'string ' + rust_debug(value.value)
        if value.kind == 'integer':
            return 'integer `' + str(value.value) + '`'
        if value.kind == 'float':
            text = repr(value.value)
            text = re.sub(r'e([+-])0+', r'e\1', text)
            text = text.replace('e+', 'e')
            return 'floating point `' + text + '`'
        if value.kind == 'boolean':
            return 'boolean `' + ('true' if value.value else 'false') + '`'
        return value.kind

    def type_error(self, value, expected, pos):
        self.fail('invalid type: ' + self.describe(value) + ', expected ' + expected, pos)

    def check_string(self, value, pos):
        if value.kind != 'string':
            self.type_error(value, 'a string', pos)
        return value.value

    def check_unsigned(self, value, pos):
        if value.kind == 'integer' and value.value < 0:
            self.fail('invalid value: ' + self.describe(value) + ', expected u64', pos)
        if value.kind != 'integer':
            self.type_error(value, 'u64', pos)
        return value.value

    def record(self, value, fields, struct_name, pos, optional=()):
        result = {}
        if value.kind == 'map':
            for key, val in value.value:
                if key.value not in fields:
                    continue
                if key.value in result:
                    self.fail('duplicate field `' + key.value + '`', pos)
                result[key.value] = val
        elif value.kind == 'sequence':
            if len(value.value) < len(fields):
                self.fail('invalid length ' + str(len(value.value)) + ', expected struct ' + struct_name + ' with ' + str(len(fields)) + ' elements', pos)
            if len(value.value) > len(fields):
                self.fail('invalid length ' + str(len(value.value)) + ', expected fewer elements in array', pos)
            result = dict(zip(fields, value.value))
        else:
            self.type_error(value, 'struct ' + struct_name, pos)
        return result

    def require(self, record, key, pos):
        if key not in record:
            self.fail('missing field `' + key + '`', pos)
        return record[key]

    def tree(self, value, pos):
        fields = ('name', 'size', 'children')
        record = self.record(value, fields, 'Reflection', pos)
        converted = {}
        # Values are validated in member order, missing fields afterward.
        for key, val in record.items():
            if key == 'name':
                converted[key] = self.check_string(val, pos)
            elif key == 'size':
                converted[key] = self.check_unsigned(val, pos)
            else:
                if val.kind != 'sequence':
                    self.type_error(val, 'a sequence', pos)
                converted[key] = [self.tree(child, pos) for child in val.value]
        for key in fields:
            self.require(record, key, pos)
        return Node(**converted)

    def shared(self, value, pos):
        record = self.record(value, ('details', 'summary'), 'JsonShared', pos)
        details = None
        summary = None
        for key, val in record.items():
            if val.kind == 'null':
                continue
            if key == 'summary':
                raw = self.record(val, SUMMARY_FIELDS, 'Summary', pos)
                summary = {k: self.check_unsigned(v, pos) for k, v in raw.items()}
                for name in SUMMARY_FIELDS:
                    self.require(raw, name, pos)
            elif key == 'details':
                if val.kind != 'sequence':
                    self.type_error(val, 'a sequence', pos)
                details = []
                for item in val.value:
                    fields = ('ino', 'size', 'links', 'paths')
                    raw = self.record(item, fields, 'ReflectionEntry', pos)
                    entry = {}
                    for name, v in raw.items():
                        if name != 'paths':
                            entry[name] = self.check_unsigned(v, pos)
                        else:
                            if v.kind != 'sequence':
                                self.type_error(v, 'a sequence', pos)
                            entry[name] = [self.check_string(p, pos) for p in v.value]
                    for name in fields:
                        self.require(raw, name, pos)
                    details.append(entry)
        if summary is None and details is not None:
            summary = summarize_links(details)
        return summary

    def read(self):
        self.whitespace()
        initial = self.pos
        value = self.value(top=True)
        if value.kind != 'map':
            pos = initial + 1 if value.kind == 'sequence' else value.end
            self.type_error(value, 'struct JsonData', pos)
        raw = collections.defaultdict(list)
        for key, val in value.value:
            raw[key.value].append(val)
        if 'schema-version' not in raw:
            self.fail('missing field `schema-version`', value.end)
        if 'unit' not in raw:
            self.fail('missing field `unit`', value.end)
        if len(raw['unit']) > 1:
            self.fail('duplicate field `unit`', value.end)
        unit = raw['unit'][0]
        if unit.kind == 'string':
            if unit.value not in ('bytes', 'blocks'):
                self.fail('unknown variant `' + unit.value + '`, expected `bytes` or `blocks`', value.end)
            unit_name = unit.value
        elif unit.kind == 'integer' and unit.value >= 0:
            if unit.value >= 2:
                self.fail('invalid value: ' + self.describe(unit) + ', expected variant index 0 <= i < 2', value.end)
            unit_name = ('bytes', 'blocks')[unit.value]
        else:
            self.type_error(unit, 'variant identifier', value.end)
        if 'tree' not in raw:
            self.fail('missing field `tree`', value.end)
        tree = self.tree(raw['tree'][0], value.end)
        summary = self.shared(raw['shared'][0], value.end) if 'shared' in raw else None
        self.whitespace()
        if self.pos != len(self.text):
            self.fail('trailing characters', self.pos + 1)
        return tree, unit_name, summary


def validate_tree(node, unit, path=None):
    path = node.name if path is None else path
    for child in node.children:
        if child.size > node.size:
            label = 'Bytes' if unit == 'bytes' else 'Blocks'
            message = '[error] InvalidInputReflection: ExcessiveChildren: ' + rust_debug(path)
            message += ' (' + label + '(' + str(node.size) + ')) is less than a child named '
            message += rust_debug(child.name) + ' (' + label + '(' + str(child.size) + '))\n'
            raise AppError(5, message)
        validate_tree(child, unit, append_path(path, child.name))


# ---------------------------------------------------------------------------
# Text rendering

class SizeFormat:
    def __init__(self, style, unit):
        self.style = 'plain' if unit == 'blocks' else style
        self.base = 1024 if style == 'binary' else 1000

    def parts(self, size):
        if self.style == 'plain':
            return str(size), ''
        if size < self.base:
            return str(size), '   '
        power = 1
        index = 0
        while index < 5 and size >= power * self.base:
            power *= self.base
            index += 1
        number = f32(f32(size) / f32(power))
        text = format(number, '.1f') + 'KM GTP'.replace(' ', '')[index - 1]
        return text[:-3], text[-3:]

    def single(self, size):
        return ''.join(self.parts(size))


def display_width(text):
    total = 0
    for c in text:
        cat = unicodedata.category(c)
        if cat in ('Cc', 'Cf', 'Cs', 'Mn', 'Me') or c == '\u200d':
            continue
        total += 2 if unicodedata.east_asian_width(c) in ('W', 'F') else 1
    return total


def rounded_share(size, total, scale):
    if total == 0:
        return 0
    product = (size * scale) & MASK
    quotient, remainder = divmod(product, total)
    return quotient + int(((remainder * 2) & MASK) >= total)


class Renderer:
    def __init__(self, root, args, unit):
        self.root = root
        self.args = args
        self.formatter = SizeFormat(args.get('bytes-format'), unit)
        self.numbers = {}
        self.integer_width = 0
        self.suffix_width = 0
        self.measure(root)

    def measure(self, node):
        parts = self.formatter.parts(node.size)
        self.numbers[id(node)] = parts
        self.integer_width = max(self.integer_width, len(parts[0]))
        self.suffix_width = max(self.suffix_width, len(parts[1]))
        for child in node.children:
            self.measure(child)

    def clip(self, node, limit, depth=0):
        available = limit - 2 * depth - 3
        if available < 0:
            return None
        name = node.name
        if display_width(name) > available:
            if available < 4:
                return None
            data = name.encode('utf-8')
            try:
                name = data[:available - 3].decode('utf-8') + '...'
            except UnicodeDecodeError:
                raise AppError(101, "\nthread 'main' panicked at src/visualizer/tree.rs:131:19:\nassertion failed: self.is_char_boundary(new_len)\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        children = []
        width = 2 * depth + 3 + display_width(name)
        for child in node.children:
            result = self.clip(child, limit, depth + 1)
            if result is not None:
                children.append(result)
                width = max(width, result[3])
        return node, name, children, width

    @staticmethod
    def terminal_width():
        for descriptor in (1, 2, 0):
            try:
                width = os.get_terminal_size(descriptor).columns
                if width:
                    return width
            except OSError:
                pass
        return 150

    def chart(self):
        number_width = self.integer_width + self.suffix_width
        overhead = number_width + 7
        column_width = self.args.get('column-width')
        if column_width is not None:
            max_tree, bars = column_width
            bars = max(1, bars)
            tree = self.clip(self.root, max_tree)
        else:
            width = self.args.get('total-width', self.terminal_width())
            if width <= 17:
                tree = self.clip(self.root, overhead)
                bars = 3 if width <= overhead else 20
            else:
                tree = self.clip(self.root, width - 17)
                bars = width - overhead - (tree[3] if tree else 0)
                if tree is not None and bars <= 0:
                    tree = self.clip(self.root, width)
                    bars = 1
                bars = max(1, bars)
        if tree is None:
            return ''
        tree_width = tree[3]
        rows = []
        top_down = self.args.flag('top-down')
        right = self.args.flag('align-right')
        end_branch = '└' if top_down else '┌'
        child_branch = '┬' if top_down else '┴'

        def visit(item, prefix, is_last, ancestry):
            node, name, children, _ = item
            line = prefix + (end_branch if is_last else '├') + '─' + (child_branch if children else '─') + name
            number, suffix = self.numbers[id(node)]
            left = number.rjust(self.integer_width) + suffix + ' ' + line
            left += ' ' * max(0, tree_width - display_width(line))
            background = [' '] * bars
            for depth, parent_size in enumerate(ancestry[1:], 1):
                shade = '░' if depth == 1 else '▒' if depth == 2 else '▓'
                length = min(bars, rounded_share(parent_size, self.root.size, bars))
                background[:length] = [shade] * length
            length = min(bars, rounded_share(node.size, self.root.size, bars))
            background[:length] = ['█'] * length
            if right:
                background.reverse()
            percent = rounded_share(node.size, self.root.size, 100)
            rows.append(left + '│' + ''.join(background) + '│' + str(percent).rjust(3) + '%\n')
            for i, child in enumerate(children):
                visit(child, prefix + ('  ' if is_last else '│ '), i == len(children) - 1, ancestry + [node.size])

        visit(tree, '', True, [])
        if not top_down:
            rows.reverse()
        return ''.join(rows)


def summary_text(summary, formatter):
    if summary is None:
        return ''
    count = summary['inodes']
    exclusive = summary['exclusive_inodes']
    if count == 0:
        return 'There are no hardlinks.\n'
    if exclusive == count:
        heading = 'No files have links outside this tree'
        inode_text = str(count)
        link_text = str(summary['all_links'])
        size_text = formatter.single(summary['shared_size'])
    elif exclusive == 0:
        heading = 'All hardlinks within this tree have links without'
        inode_text = str(count)
        link_text = str(summary['all_links']) + ' total, ' + str(summary['detected_links']) + ' detected'
        size_text = formatter.single(summary['shared_size'])
    else:
        heading = 'Some files have links outside this tree'
        inode_text = str(count) + ' total, ' + str(exclusive) + ' exclusive'
        link_text = str(summary['all_links']) + ' total, ' + str(summary['detected_links']) + ' detected, ' + str(summary['exclusive_links']) + ' exclusive'
        size_text = formatter.single(summary['shared_size']) + ' total, ' + formatter.single(summary['exclusive_shared_size']) + ' exclusive'
    return ('Hardlinks detected! ' + heading + '\n'
            '* Number of shared inodes: ' + inode_text + '\n'
            '* Total number of links: ' + link_text + '\n'
            '* Total shared size: ' + size_text + '\n')


def main():
    args = Arguments(sys.argv[1:])
    if args.flag('json-input'):
        if args.files:
            raise AppError(4, '[error] JsonInputArgConflict: Arguments exist alongside --json-input\n')
        raw = sys.stdin.buffer.read()
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError as ex:
            reader = JsonReader(raw.decode('utf-8', 'replace'))
            reader.fail('invalid unicode code point', ex.start + 1)
        root, unit, summary = JsonReader(text).read()
        validate_tree(root, unit)
        renderer = Renderer(root, args, unit)
        out = renderer.chart()
        if summary is not None:
            out += summary_text(summary, renderer.formatter) + '\n'
        sys.stdout.write(out)
        return
    root, details, summary = Collector(args).collect()
    unit = 'blocks' if args.get('quantity') == 'block-count' else 'bytes'
    if args.flag('json-output'):
        output = {'schema-version': SCHEMA, 'pdu': VERSION, 'unit': unit,
                  'tree': root.as_json()}
        if details:
            shared = {}
            if not args.flag('omit-json-shared-details'):
                shared['details'] = details
            if not args.flag('omit-json-shared-summary'):
                shared['summary'] = summary
            if shared:
                output['shared'] = shared
        sys.stdout.write(json.dumps(output, ensure_ascii=False, separators=(',', ':')))
    else:
        renderer = Renderer(root, args, unit)
        sys.stdout.write(renderer.chart() + summary_text(summary, renderer.formatter))


if __name__ == '__main__':
    sys.setrecursionlimit(20000)
    try:
        main()
    except AppError as error:
        sys.stderr.write(error.message)
        sys.exit(error.code)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(1)
